{
  "assessment": "58-year-old man with severe community-acquired pneumonia (multiple ATS/IDSA major and minor severity criteria, CURB-65 score 4), hemodynamically stable but high-risk, requiring high-dependency unit admission.",
  "regimen": [
    {
      "drug": "ceftriaxone",
      "dose": "2 g",
      "route": "intravenous",
      "frequency": "once daily"
    },
    {
      "drug": "azithromycin",
      "dose": "500 mg",
      "route": "intravenous",
      "frequency": "once daily"
    }
  ],
  "rationale": "Per 2019 ATS/IDSA guidelines for severe community-acquired pneumonia (admitted to ICU/high-dependency unit), empiric therapy should cover both typical (e.g., Streptococcus pneumoniae) and atypical pathogens (e.g., Legionella, Mycoplasma). Ceftriaxone provides broad-spectrum gram-positive and some gram-negative coverage, while azithromycin covers atypical organisms. This combination is recommended for severe CAP in adults without risk factors for Pseudomonas aeruginosa. No penicillin allergy or MRSA risk factors are present.",
  "confidence": "very high"
}

