{
  "assessment": "Severe community-acquired pneumonia (CAP) in a 58-year-old man with CURB-65 score 3 and multiple ATS/IDSA minor severity criteria (respiratory rate ≥30, PaO2/FiO2 ≤250, confusion, uraemia, hypotension requiring fluids, leukocytosis, multilobar involvement). No major severity criteria, no prior MRSA or Pseudomonas risk factors, and no drug allergies.",
  "regimen": [
    {
      "drug": "ceftriaxone",
      "dose": "2 g",
      "route": "intravenous",
      "frequency": "once daily"
    },
    {
      "drug": "azithromycin",
      "dose": "500 mg",
      "route": "intravenous",
      "frequency": "once daily"
    }
  ],
  "rationale": "Guidelines recommend empiric therapy for severe CAP with a beta-lactam (ceftriaxone) plus either a macrolide (azithromycin) or a respiratory fluoroquinolone. Ceftriaxone covers typical bacterial pathogens including S. pneumoniae, while azithromycin provides coverage for atypical pathogens (e.g., Mycoplasma pneumoniae, Chlamydia pneumoniae). This combination aligns with 2019 ATS/IDSA recommendations for severe CAP without risk factors for MRSA or Pseudomonas. Intravenous route is appropriate given severity and patient status in high-dependency unit.",
  "confidence": "very high"
}

